// Google Sign-In configuration
// GOOGLE_CLIENT_ID is loaded from config.js (generated by Terraform)

var AUTH_STORAGE_KEY = 'soc_auth_token';
var USER_STORAGE_KEY = 'soc_auth_user';

function getStoredToken() {
    try {
        var stored = sessionStorage.getItem(AUTH_STORAGE_KEY);
        if (stored) {
            var data = JSON.parse(stored);
            // Check if token is expired
            if (data.expires_at && Date.now() < data.expires_at) {
                return data.token;
            }
            clearStoredAuth();
        }
    } catch (e) {
        console.error('Error reading stored token:', e);
    }
    return null;
}

function storeToken(token, expiresIn) {
    try {
        sessionStorage.setItem(AUTH_STORAGE_KEY, JSON.stringify({
            token: token,
            expires_at: Date.now() + (expiresIn * 1000)
        }));
    } catch (e) {
        console.error('Error storing token:', e);
    }
}

function getStoredUser() {
    try {
        var stored = sessionStorage.getItem(USER_STORAGE_KEY);
        if (stored) {
            return JSON.parse(stored);
        }
    } catch (e) {
        console.error('Error reading stored user:', e);
    }
    return null;
}

function storeUser(user) {
    try {
        sessionStorage.setItem(USER_STORAGE_KEY, JSON.stringify(user));
    } catch (e) {
        console.error('Error storing user:', e);
    }
}

function clearStoredAuth() {
    sessionStorage.removeItem(AUTH_STORAGE_KEY);
    sessionStorage.removeItem(USER_STORAGE_KEY);
}

function parseIdToken(credential) {
    try {
        var payload = JSON.parse(atob(credential.split('.')[1]));
        return {
            email: payload.email,
            name: payload.name || payload.email,
            picture: payload.picture || null,
            sub: payload.sub,
            exp: payload.exp
        };
    } catch (e) {
        console.error('Error parsing ID token:', e);
        return null;
    }
}

function showLoginScreen() {
    document.getElementById('loginScreen').style.display = 'flex';
    document.getElementById('appContent').style.display = 'none';
}

function showAppContent() {
    document.getElementById('loginScreen').style.display = 'none';
    document.getElementById('appContent').style.display = 'block';
}

function updateUserDisplay(user) {
    var userInfo = document.getElementById('userInfo');
    if (userInfo && user) {
        var avatarHtml = user.picture
            ? '<img src="' + user.picture + '" alt="Profile" class="user-avatar">'
            : '<div class="user-avatar-placeholder">' + user.email.charAt(0).toUpperCase() + '</div>';
        userInfo.innerHTML = avatarHtml +
            '<span class="user-email">' + user.email + '</span>' +
            '<button onclick="signOut()" class="sign-out-btn">Sign Out</button>';
        userInfo.style.display = 'flex';
    }
}

function handleCredentialResponse(response) {
    var user = parseIdToken(response.credential);
    if (!user) {
        console.error('Failed to parse credential');
        return;
    }

    // Token expires in ~1 hour, store with expiration
    var expiresIn = user.exp - Math.floor(Date.now() / 1000);
    storeToken(response.credential, expiresIn);
    storeUser(user);

    updateUserDisplay(user);
    showAppContent();

    if (typeof loadAllSimulations === 'function') {
        loadAllSimulations();
    }
}

function signOut() {
    clearStoredAuth();
    google.accounts.id.disableAutoSelect();
    showLoginScreen();
    initGoogleSignIn();
}

function getAccessToken() {
    return getStoredToken();
}

function initGoogleSignIn() {
    if (!GOOGLE_CLIENT_ID) {
        document.getElementById('loginScreen').innerHTML =
            '<div class="login-container"><div class="login-error">Google Sign-In not configured.<br>Set GOOGLE_CLIENT_ID in auth.js</div></div>';
        return;
    }

    google.accounts.id.initialize({
        client_id: GOOGLE_CLIENT_ID,
        callback: handleCredentialResponse,
        auto_select: true
    });

    google.accounts.id.renderButton(
        document.getElementById('googleSignInButton'),
        { theme: 'outline', size: 'large', text: 'signin_with', shape: 'rectangular' }
    );

    google.accounts.id.prompt();
}

function initAuth() {
    // Check for existing valid session
    var token = getStoredToken();
    if (token) {
        var user = getStoredUser();
        if (user) {
            updateUserDisplay(user);
            showAppContent();
            if (typeof loadAllSimulations === 'function') {
                loadAllSimulations();
            }
            return;
        }
    }

    // No valid session, show login
    showLoginScreen();
    initGoogleSignIn();
}

// Initialize when Google library loads
function onGoogleLibraryLoad() {
    initAuth();
}

// Check if Google library is already loaded
if (typeof google !== 'undefined' && google.accounts) {
    document.addEventListener('DOMContentLoaded', initAuth);
} else {
    // Wait for it
    window.onGoogleLibraryLoad = onGoogleLibraryLoad;
}
